function primesBelow(n: number): number {
  if (n < 3) return 0;
  const composite = new Uint8Array(n);
  for (let p = 2; p * p < n; p++) {
    if (composite[p]) continue;
    for (let m = p * p; m < n; m += p) composite[m] = 1;
  }
  let count = 0;
  for (let k = 2; k < n; k++) if (!composite[k]) count++;
  return count;
}

